+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Scientific Calculator</title>
+    <link rel="preconnect" href="https://fonts.googleapis.com">
+    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
+    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&family=JetBrains+Mono:wght@400;600;700&display=swap" rel="stylesheet">
+    <style>
+        body {
+            font-family: 'Inter', sans-serif;
+            background-color: #101820;
+        }
+        .calculator {
+            width: 400px;
+            height: 600px;
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            border-radius: 20px;
+            padding: 20px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .display {
+            width: 100%;
+            height: 100px;
+            background-color: #1a2336;
+            color: #fff;
+            font-size: 36px;
+            font-weight: bold;
+            text-align: right;
+            padding: 20px;
+            border-radius: 10px;
+        }
+        .button {
+            width: 80px;
+            height: 80px;
+            background-color: #1a2336;
+            color: #fff;
+            font-size: 24px;
+            font-weight: bold;
+            border: none;
+            border-radius: 10px;
+            cursor: pointer;
+            transition: background-color 0.2s ease;
+        }
+        .button:hover {
+            background-color: #2c3550;
+        }
+        .history {
+            width: 100%;
+            height: 200px;
+            background-color: #1a2336;
+            color: #fff;
+            font-size: 18px;
+            font-weight: bold;
+            text-align: left;
+            padding: 20px;
+            border-radius: 10px;
+            overflow-y: auto;
+        }
+    </style>
+</head>
+<body>
+    <div class="calculator">
+        <div class="display" id="display"></div>
+        <div class="history" id="history"></div>
+        <div class="buttons">
+            <button class="button" id="clear">C</button>
+            <button class="button" id="backspace">DEL</button>
+            <button class="button" id="equals">=</button>
+            <button class="button" id="add">+</button>
+            <button class="button" id="subtract">-</button>
+            <button class="button" id="multiply">*</button>
+            <button class="button" id="divide">/</button>
+            <button class="button" id="sin">sin</button>
+            <button class="button" id="cos">cos</button>
+            <button class="button" id="tan">tan</button>
+            <button class="button" id="log">log</button>
+            <button class="button" id="ln">ln</button>
+            <button class="button" id="exp">x^y</button>
+            <button class="button" id="sqrt">sqrt</button>
+            <button class="button" id="zero">0</button>
+            <button class="button" id="one">1</button>
+            <button class="button" id="two">2</button>
+            <button class="button" id="three">3</button>
+            <button class="button" id="four">4</button>
+            <button class="button" id="five">5</button>
+            <button class="button" id="six">6</button>
+            <button class="button" id="seven">7</button>
+            <button class="button" id="eight">8</button>
+            <button class="button" id="nine">9</button>
+        </div>
+    </div>
+    <script>
+        const display = document.getElementById('display');
+        const history = document.getElementById('history');
+        let currentExpression = '';
+        let historyExpressions = [];
+        
+        document.addEventListener('keydown', (e) => {
+            if (e.key === 'Enter') {
+                calculateExpression();
+            } else if (e.key === 'Backspace') {
+                backspace();
+            } else if (e.key === 'c' || e.key === 'C') {
+                clearDisplay();
+            } else if (e.key >= '0' && e.key <= '9') {
+                appendToExpression(e.key);
+            } else if (e.key === '+' || e.key === '-' || e.key === '*' || e.key === '/') {
+                appendToExpression(e.key);
+            }
+        });
+        
+        function calculateExpression() {
+            try {
+                const result = eval(currentExpression);
+                display.textContent = result;
+                historyExpressions.push(currentExpression + ' = ' + result);
+                history.innerHTML = '';
+                historyExpressions.forEach((expression) => {
+                    const paragraph = document.createElement('p');
+                    paragraph.textContent = expression;
+                    history.appendChild(paragraph);
+                });
+                currentExpression = '';
+            } catch (e) {
+                display.textContent = 'Error';
+            }
+        }
+        
+        function backspace() {
+            currentExpression = currentExpression.slice(0, -1);
+            display.textContent = currentExpression;
+        }
+        
+        function clearDisplay() {
+            currentExpression = '';
+            display.textContent = '';
+            historyExpressions = [];
+            history.innerHTML = '';
+        }
+        
+        function appendToExpression(value) {
+            currentExpression += value;
+            display.textContent = currentExpression;
+        }
+        
+        document.getElementById('clear').addEventListener('click', clearDisplay);
+        document.getElementById('backspace').addEventListener('click', backspace);
+        document.getElementById('equals').addEventListener('click', calculateExpression);
+        document.getElementById('add').addEventListener('click', () => appendToExpression('+'));
+        document.getElementById('subtract').addEventListener('click', () => appendToExpression('-'));
+        document.getElementById('multiply').addEventListener('click', () => appendToExpression('*'));
+        document.getElementById('divide').addEventListener('click', () => appendToExpression('/'));
+        document.getElementById('sin').addEventListener('click', () => appendToExpression('Math.sin('));
+        document.getElementById('cos').addEventListener('click', () => appendToExpression('Math.cos('));
+        document.getElementById('tan').addEventListener('click', () => appendToExpression('Math.tan('));
+        document.getElementById('log').addEventListener('click', () => appendToExpression('Math.log('));
+        document.getElementById('ln').addEventListener('click', () => appendToExpression('Math.log('));
+        document.getElementById('exp').addEventListener('click', () => appendToExpression('**'));
+        document.getElementById('sqrt').addEventListener('click', () => appendToExpression('Math.sqrt('));
+        document.getElementById('zero').addEventListener('click', () => appendToExpression('0'));
+        document.getElementById('one').addEventListener('click', () => appendToExpression('1'));
+        document.getElementById('two').addEventListener('click', () => appendToExpression('2'));
+        document.getElementById('three').addEventListener('click', () => appendToExpression('3'));
+        document.getElementById('four').addEventListener('click', () => appendToExpression('4'));
+        document.getElementById('five').addEventListener('click', () => appendToExpression('5'));
+        document.getElementById('six').addEventListener('click', () => appendToExpression('6'));
+        document.getElementById('seven').addEventListener('click', () => appendToExpression('7'));
+        document.getElementById('eight').addEventListener('click', () => appendToExpression('8'));
+        document.getElementById('nine').addEventListener('click', () => appendToExpression('9'));
+    </script>
+</body>
+</html>

